insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction","weather_type") values
('weather-pongi-raincoat','fish','노란 우비 퐁이','노란 우비 자락을 나부끼며 물살을 가르는 퐁이. 비가 오는 동안 만나볼 수 있어요.','0.18','0.6','0.03',120,'common','fish/normal/weather-pongi-raincoat_v1_thumbnail.png',2000,'fish/normal/weather-pongi-raincoat_v1_sprite.png',null,'swim',true,'both','rain'),
('weather-pongi-leaf-umbrella','fish','연잎 우산 퐁이','커다란 연잎을 한 손으로 꼭 잡고 유유히 헤엄치는 퐁이. 연잎 끝의 물방울을 소중히 지켜요.','0.12','0.48','0.026',120,'common','fish/normal/weather-pongi-leaf-umbrella_v1_thumbnail.png',2200,'fish/normal/weather-pongi-leaf-umbrella_v1_sprite.png',null,'swim',true,'both','rain'),
('weather-pongi-red-scarf','fish','목도리 퐁이','빨간 목도리를 길게 휘날리며 헤엄치는 퐁이. 머리 위에 내려앉은 눈도 잊을 만큼 신이 났어요.','0.2','0.65','0.029',120,'common','fish/normal/weather-pongi-red-scarf_v1_thumbnail.png',2100,'fish/normal/weather-pongi-red-scarf_v1_sprite.png',null,'swim',true,'both','snow'),
('weather-pongi-snowflake-cape','fish','눈꽃 망토 퐁이','눈꽃 자수가 놓인 푸른 망토를 두른 퐁이. 꼬리를 흔들 때마다 망토 끝이 부드럽게 일렁여요.','0.16','0.58','0.025',120,'common','fish/normal/weather-pongi-snowflake-cape_v1_thumbnail.png',2400,'fish/normal/weather-pongi-snowflake-cape_v1_sprite.png',null,'swim',true,'both','snow'),
('weather-pongi-sand-goggles','fish','모래바람 고글 퐁이','모래바람에도 끄떡없는 고글과 스카프를 착용한 퐁이. 앞발을 힘차게 저으며 바다를 탐험해요.','0.28','0.72','0.034',120,'common','fish/normal/weather-pongi-sand-goggles_v1_thumbnail.png',2000,'fish/normal/weather-pongi-sand-goggles_v1_sprite.png',null,'swim',true,'both','dust'),
('weather-pongi-desert-traveler','fish','사막 여행자 퐁이','터번과 작은 여행 가방을 챙겨 길을 나선 퐁이. 나침반을 달랑이며 새로운 물길을 찾아 헤엄쳐요.','0.24','0.68','0.027',120,'common','fish/normal/weather-pongi-desert-traveler_v1_thumbnail.png',2300,'fish/normal/weather-pongi-desert-traveler_v1_sprite.png',null,'swim',true,'both','dust'),
('weather-pongi-comet-tail','fish','유성 꼬리 퐁이','꼬리 끝에 푸른 별 장식을 단 퐁이. 밤하늘을 가르는 유성처럼 날렵하게 물살을 미끄러져요.','0.12','0.52','0.036',120,'common','fish/normal/weather-pongi-comet-tail_v1_thumbnail.png',2500,'fish/normal/weather-pongi-comet-tail_v1_sprite.png',null,'swim',true,'both','meteor'),
('weather-pongi-star-collector','fish','별 줍는 퐁이','작은 유리병에 별 조각을 모은 퐁이. 병을 품에 꼭 안고 뒷발로 조심조심 헤엄쳐요.','0.2','0.62','0.025',120,'common','fish/normal/weather-pongi-star-collector_v1_thumbnail.png',2400,'fish/normal/weather-pongi-star-collector_v1_sprite.png',null,'swim',true,'both','meteor'),
('weather-pongi-cherry-cape','fish','벚꽃 망토 퐁이','분홍 꽃잎을 겹겹이 두른 퐁이. 물결을 따라 펼쳐지는 망토가 작은 봄날을 데려와요.','0.16','0.56','0.028',120,'common','fish/normal/weather-pongi-cherry-cape_v1_thumbnail.png',2300,'fish/normal/weather-pongi-cherry-cape_v1_sprite.png',null,'swim',true,'both','blossom'),
('weather-pongi-flower-bouquet','fish','꽃다발 퐁이','머리에 데이지를 꽂고 꽃다발을 안은 퐁이. 소중한 친구에게 꽃을 전하러 뒷발을 저으며 헤엄쳐요.','0.22','0.64','0.026',120,'common','fish/normal/weather-pongi-flower-bouquet_v1_thumbnail.png',2200,'fish/normal/weather-pongi-flower-bouquet_v1_sprite.png',null,'swim',true,'both','blossom')
